    /// The current selector anchor is minted from a fully reverified immutable
    /// control entry. The durable head contributes only lifecycle, generation,
    /// close facts, and the exact transition ID to reverify.
    #[test]
    fn retained_metadata_current_anchor_comes_from_reverified_evidence() {
        let cid = Uuid::new_v4();
        let entry = build_real_creation_entry(*cid.as_bytes());
        let current_transition_id = signed_creation_transition_id(&entry);
        let received_at = serde_json::from_slice::<Value>(&entry.public_row_json).unwrap()
            ["receivedAt"]
            .as_str()
            .unwrap()
            .to_owned();
        let authority =
            HistoricalRehydrationAuthority::new(entry.cid, entry.head_next_entry_seq).unwrap();
        let current = authority
            .hydrate_historical_control_from_durable_bytes(
                entry.public_row_json.clone(),
                entry.raw_wrapper.clone(),
                &entry.public_key,
            )
            .expect("creation entry re-verifies");

        let catalog = RetainedMetadataCatalogHead {
            conversation_lifecycle: "active",
            generation_state_lifecycle: "active",
            current_generation: 0,
            current_transition_id,
            close_transition_id: None,
            close_seq: None,
            closed_at: None,
        };
        let (head, evidence) =
            retained_metadata_head_from_current_evidence(catalog, current.clone())
                .expect("verified creation mints the selector anchor");

        assert_eq!(head.current_kind, "creation");
        assert_eq!(head.current_transition_id, current_transition_id);
        assert_eq!(head.current_seq, 1);
        assert_eq!(
            head.current_received_at,
            ServerTimestamp::from_canonical_stored(&received_at).unwrap()
        );
        assert_eq!(
            Uuid::from_bytes(*evidence.transition_id()),
            current_transition_id
        );
        assert_eq!(evidence.seq(), 1);
        assert_eq!(evidence.received_at(), head.current_received_at);

        assert!(matches!(
            retained_metadata_head_from_current_evidence(
                RetainedMetadataCatalogHead {
                    current_transition_id: Uuid::new_v4(),
                    ..catalog
                },
                current,
            ),
            Err(MetadataHydrationError::InvalidProvenance)
        ));

        let unsigned_transition_id = Uuid::new_v4();
        let unsigned_transition =
            TransitionEvidence::new(1, *unsigned_transition_id.as_bytes(), [0xA1; 32]).unwrap();
        assert!(matches!(
            retained_metadata_head_from_current_evidence(
                RetainedMetadataCatalogHead {
                    current_transition_id: unsigned_transition_id,
                    ..catalog
                },
                PersistedControlAuthority::Transition(unsigned_transition),
            ),
            Err(MetadataHydrationError::InvalidProvenance)
        ));

        let actor = DeviceIdentity::new(
            PrincipalId::new(entry.actor_did.into_bytes()).unwrap(),
            *entry.actor_device_id.as_bytes(),
        )
        .unwrap();
        let request = RequestEvidence::for_test(
            RequestEntryKind::ResetRequest,
            1,
            *Uuid::new_v4().as_bytes(),
            actor,
            entry.cid,
            ServerTimestamp::from_canonical_stored(&received_at).unwrap(),
            0xA2,
        )
        .unwrap();
        assert!(matches!(
            retained_metadata_head_from_current_evidence(
                catalog,
                PersistedControlAuthority::Request(request),
            ),
            Err(MetadataHydrationError::InvalidProvenance)
        ));
    }

    /// This pure boundary characterizes catalog shapes that deferred constraints
    /// make impossible to commit. Production selection must remain closed over
    /// transition kind, same-generation sequence, and terminal lifecycle shape.
    #[test]
    fn retained_metadata_selector_is_closed_over_kind_sequence_and_lifecycle() {
        let current_transition_id = Uuid::new_v4();
        let retained_transition_id = Uuid::new_v4();
        let accepted_at = DateTime::parse_from_rfc3339("2030-01-01T00:00:02.000Z")
            .unwrap()
            .with_timezone(&Utc);
        let active = RetainedMetadataHead {
            conversation_lifecycle: "active",
            generation_state_lifecycle: "active",
            current_generation: 0,
            current_kind: "acceptConversation",
            current_transition_id,
            current_seq: 2,
            current_received_at: ServerTimestamp::from_canonical_stored("2030-01-01T00:00:02.000Z")
                .unwrap(),
            close_transition_id: None,
            close_seq: None,
            closed_at: None,
        };
        let retained = RetainedMetadataCandidate {
            transition_id: retained_transition_id,
            generation: 0,
            seq: 1,
            accepted_at,
        };
        for snapshotless_kind in ["policy", "acceptConversation", "leavePolicy"] {
            assert_eq!(
                select_retained_metadata_producer(
                    RetainedMetadataHead {
                        current_kind: snapshotless_kind,
                        ..active
                    },
                    vec![retained],
                )
                .unwrap(),
                retained_transition_id,
                "{snapshotless_kind} retains the earlier producer"
            );
        }

        let current_snapshot = RetainedMetadataCandidate {
            transition_id: current_transition_id,
            generation: 0,
            seq: 2,
            accepted_at,
        };
        for snapshot_kind in [
            "creation",
            "commit",
            "metadata",
            "leafRecovery",
            "leaveCommit",
            "resetActivation",
        ] {
            assert_eq!(
                select_retained_metadata_producer(
                    RetainedMetadataHead {
                        current_kind: snapshot_kind,
                        ..active
                    },
                    vec![retained, current_snapshot],
                )
                .unwrap(),
                current_transition_id,
                "{snapshot_kind} selects its own snapshot"
            );
        }

        assert!(matches!(
            select_retained_metadata_producer(active, Vec::new()),
            Err(MetadataHydrationError::ProvenanceMissing)
        ));
        for snapshot_kind in [
            "creation",
            "commit",
            "metadata",
            "leafRecovery",
            "leaveCommit",
            "resetActivation",
        ] {
            assert!(matches!(
                select_retained_metadata_producer(
                    RetainedMetadataHead {
                        current_kind: snapshot_kind,
                        ..active
                    },
                    vec![retained],
                ),
                Err(MetadataHydrationError::OutOfDomain)
            ));
        }
        for candidate in [
            RetainedMetadataCandidate {
                transition_id: current_transition_id,
                generation: 0,
                seq: 2,
                accepted_at,
            },
            RetainedMetadataCandidate {
                transition_id: Uuid::new_v4(),
                generation: 0,
                seq: 3,
                accepted_at,
            },
            RetainedMetadataCandidate {
                transition_id: retained_transition_id,
                generation: 1,
                seq: 1,
                accepted_at,
            },
        ] {
            assert!(matches!(
                select_retained_metadata_producer(active, vec![candidate]),
                Err(MetadataHydrationError::OutOfDomain)
            ));
        }
        assert!(matches!(
            select_retained_metadata_producer(
                RetainedMetadataHead {
                    current_kind: "unknownKind",
                    ..active
                },
                vec![retained],
            ),
            Err(MetadataHydrationError::OutOfDomain)
        ));

        let closed = RetainedMetadataHead {
            conversation_lifecycle: "superseded",
            generation_state_lifecycle: "superseded",
            current_kind: "closeConversation",
            close_transition_id: Some(current_transition_id),
            close_seq: Some(2),
            closed_at: Some(accepted_at),
            ..active
        };
        assert_eq!(
            select_retained_metadata_producer(closed, vec![retained]).unwrap(),
            retained_transition_id
        );
        for malformed in [
            RetainedMetadataHead {
                conversation_lifecycle: "active",
                ..closed
            },
            RetainedMetadataHead {
                generation_state_lifecycle: "active",
                ..closed
            },
            RetainedMetadataHead {
                current_kind: "policy",
                ..closed
            },
            RetainedMetadataHead {
                close_transition_id: Some(Uuid::new_v4()),
                ..closed
            },
            RetainedMetadataHead {
                close_seq: Some(3),
                ..closed
            },
            RetainedMetadataHead {
                closed_at: Some(
                    DateTime::parse_from_rfc3339("2030-01-01T00:00:03.000Z")
                        .unwrap()
                        .with_timezone(&Utc),
                ),
                ..closed
            },
        ] {
            assert!(matches!(
                select_retained_metadata_producer(malformed, vec![retained]),
                Err(MetadataHydrationError::OutOfDomain)
            ));
        }

        let newer_by_sequence = RetainedMetadataCandidate {
            transition_id: Uuid::new_v4(),
            generation: 0,
            seq: 2,
            accepted_at: DateTime::parse_from_rfc3339("2029-01-01T00:00:00.000Z")
                .unwrap()
                .with_timezone(&Utc),
        };
        let misleading_later_time = RetainedMetadataCandidate {
            accepted_at: DateTime::parse_from_rfc3339("2031-01-01T00:00:00.000Z")
                .unwrap()
                .with_timezone(&Utc),
            ..retained
        };
        assert_eq!(
            select_retained_metadata_producer(
                RetainedMetadataHead {
                    current_kind: "policy",
                    current_seq: 3,
                    ..active
                },
                vec![misleading_later_time, newer_by_sequence],
            )
            .unwrap(),
            newer_by_sequence.transition_id,
            "entry sequence, never accepted_at, chooses the retained predecessor"
        );

        let equal_sequence_peer = RetainedMetadataCandidate {
            transition_id: Uuid::new_v4(),
            ..newer_by_sequence
        };
        for ambiguous in [
            vec![newer_by_sequence, equal_sequence_peer],
            vec![equal_sequence_peer, newer_by_sequence],
        ] {
            assert!(matches!(
                select_retained_metadata_producer(
                    RetainedMetadataHead {
                        current_kind: "policy",
                        current_seq: 3,
                        ..active
                    },
                    ambiguous,
                ),
                Err(MetadataHydrationError::OutOfDomain)
            ));
        }
    }

