        fn g6_raw_literal_end(bytes: &[u8], start: usize) -> Option<usize> {
            let mut cursor = start;
            if bytes.get(cursor) == Some(&b'b') {
                cursor += 1;
            }
            if bytes.get(cursor) != Some(&b'r') {
                return None;
            }
            cursor += 1;
            let mut hashes = 0;
            while bytes.get(cursor) == Some(&b'#') {
                hashes += 1;
                cursor += 1;
            }
            if bytes.get(cursor) != Some(&b'"') {
                return None;
            }
            cursor += 1;
            while cursor < bytes.len() {
                if bytes[cursor] == b'"'
                    && bytes
                        .get(cursor + 1..cursor + 1 + hashes)
                        .is_some_and(|suffix| suffix.iter().all(|byte| *byte == b'#'))
                {
                    return Some(cursor + 1 + hashes);
                }
                cursor += 1;
            }
            Some(bytes.len())
        }

        fn g6_quoted_literal_end(bytes: &[u8], quote: usize) -> usize {
            let mut cursor = quote + 1;
            while cursor < bytes.len() {
                match bytes[cursor] {
                    b'\\' => cursor = (cursor + 2).min(bytes.len()),
                    b'"' => return cursor + 1,
                    _ => cursor += 1,
                }
            }
            bytes.len()
        }

        fn g6_char_literal_end(source: &str, quote: usize) -> Option<usize> {
            let bytes = source.as_bytes();
            let mut cursor = quote + 1;
            match *bytes.get(cursor)? {
                b'\\' => {
                    cursor += 1;
                    match *bytes.get(cursor)? {
                        b'x' => cursor += 3,
                        b'u' if bytes.get(cursor + 1) == Some(&b'{') => {
                            cursor += 2;
                            while !matches!(bytes.get(cursor), Some(b'}') | None) {
                                cursor += 1;
                            }
                            cursor += 1;
                        }
                        _ => cursor += 1,
                    }
                }
                b'\n' | b'\r' | b'\'' => return None,
                _ => {
                    let character = source[cursor..].chars().next()?;
                    cursor += character.len_utf8();
                }
            }
            (bytes.get(cursor) == Some(&b'\'')).then_some(cursor + 1)
        }

        /// Produce same-length code and literal projections. Comments are
        /// absent from both; literals are absent from `code`, and non-literal
        /// code is absent from `literals`. Keeping byte positions stable lets
        /// source-item extraction use compiler-like lexical boundaries without
        /// a comment or raw SQL brace changing the selected item.
        fn g6_source_projections(source: &str) -> (String, String) {
            let bytes = source.as_bytes();
            let mut code = vec![b' '; bytes.len()];
            let mut literals = vec![b' '; bytes.len()];
            let mut cursor = 0;
            while cursor < bytes.len() {
                if bytes.get(cursor..cursor + 2) == Some(b"//") {
                    cursor += 2;
                    while cursor < bytes.len() && bytes[cursor] != b'\n' {
                        cursor += 1;
                    }
                    if cursor < bytes.len() {
                        code[cursor] = b'\n';
                        literals[cursor] = b'\n';
                        cursor += 1;
                    }
                    continue;
                }
                if bytes.get(cursor..cursor + 2) == Some(b"/*") {
                    let mut depth = 1_u64;
                    cursor += 2;
                    while cursor < bytes.len() && depth > 0 {
                        if bytes.get(cursor..cursor + 2) == Some(b"/*") {
                            depth += 1;
                            cursor += 2;
                        } else if bytes.get(cursor..cursor + 2) == Some(b"*/") {
                            depth -= 1;
                            cursor += 2;
                        } else {
                            if bytes[cursor] == b'\n' {
                                code[cursor] = b'\n';
                                literals[cursor] = b'\n';
                            }
                            cursor += 1;
                        }
                    }
                    continue;
                }
                if let Some(end) = g6_raw_literal_end(bytes, cursor) {
                    literals[cursor..end].copy_from_slice(&bytes[cursor..end]);
                    cursor = end;
                    continue;
                }
                if bytes[cursor] == b'"'
                    || (bytes[cursor] == b'b' && bytes.get(cursor + 1) == Some(&b'"'))
                {
                    let quote = cursor + usize::from(bytes[cursor] == b'b');
                    let end = g6_quoted_literal_end(bytes, quote);
                    literals[cursor..end].copy_from_slice(&bytes[cursor..end]);
                    cursor = end;
                    continue;
                }
                let char_quote = if bytes[cursor] == b'\'' {
                    Some(cursor)
                } else if bytes[cursor] == b'b' && bytes.get(cursor + 1) == Some(&b'\'') {
                    Some(cursor + 1)
                } else {
                    None
                };
                if let Some(quote) = char_quote {
                    if let Some(end) = g6_char_literal_end(source, quote) {
                        literals[cursor..end].copy_from_slice(&bytes[cursor..end]);
                        cursor = end;
                        continue;
                    }
                }
                code[cursor] = bytes[cursor];
                cursor += 1;
            }
            (
                String::from_utf8(code).expect("Rust source code projection remains UTF-8"),
                String::from_utf8(literals).expect("Rust source literal projection remains UTF-8"),
            )
        }

        fn g6_source_code(source: &str) -> String {
            g6_source_projections(source).0
        }

        fn g6_source_literals(source: &str) -> String {
            g6_source_projections(source).1
        }

        fn g6_compact_code(source: &str) -> String {
            g6_source_code(source)
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" ")
        }

        fn g6_source_item<'a>(source: &'a str, marker: &str) -> &'a str {
            let code = g6_source_code(source);
            let start = code
                .find(marker)
                .unwrap_or_else(|| panic!("missing G6 source marker: {marker}"));
            let open = code[start..]
                .find('{')
                .map(|offset| start + offset)
                .unwrap_or_else(|| panic!("missing opening brace for: {marker}"));
            let mut depth = 0_i64;
            for (offset, byte) in code.as_bytes()[open..].iter().enumerate() {
                match byte {
                    b'{' => depth += 1,
                    b'}' => {
                        depth -= 1;
                        if depth == 0 {
                            return &source[start..=open + offset];
                        }
                    }
                    _ => {}
                }
            }
            panic!("unterminated G6 source item: {marker}");
        }

        #[test]
        fn g6_source_item_ignores_comment_and_literal_decoys() {
            let source = r####"
                // fn selected() { COMMENT_DECOY }
                const DECOY: &str = r###"fn selected() { RAW_DECOY }"###;
                fn selected() {
                    let ordinary = "} STRING_DECOY {";
                    let raw = r##"} RAW_BODY_DECOY {"##;
                    if true { let character = '}'; }
                    CODE_SENTINEL
                }
                fn following() { FOLLOWING_SENTINEL }
            "####;
            let item = g6_source_item(source, "fn selected()");
            let code = g6_source_code(item);
            let literals = g6_source_literals(item);
            assert!(code.contains("CODE_SENTINEL"));
            assert!(!code.contains("FOLLOWING_SENTINEL"));
            assert!(!code.contains("COMMENT_DECOY"));
            assert!(!code.contains("STRING_DECOY"));
            assert!(literals.contains("STRING_DECOY"));
            assert!(literals.contains("RAW_BODY_DECOY"));
        }

        #[test]
        fn g6_production_authority_path_has_no_raw_business_guard() {
            let core = include_str!("../src/chat_protocol/repository/core.rs");
            let state_machine = include_str!("../src/chat_protocol/state_machine.rs");
            let execution = include_str!("../src/chat_protocol/repository/execution_context.rs");

            let scope_seal = g6_source_item(core, "pub(crate) async fn seal_g6_scope_authority(");
            let scope_seal = g6_source_code(scope_seal);
            assert!(scope_seal.contains("scope: &ScopeBoundBusinessAuthority"));
            let planner =
                g6_source_item(state_machine, "pub(crate) fn plan_device_revocation_batch(");
            let planner = g6_source_code(planner);
            assert!(planner.contains("actor_registration: LockedRegistrationProjection"));
            let executor_binding = g6_source_item(execution, "fn validate_g6_prelude_binding(");
            let executor_binding = g6_source_code(executor_binding);
            assert!(
                executor_binding
                    .contains("prelude.authority_scope_digest() != plan.authority_scope_digest()"),
                "executor must anchor the G6 prelude to the planner's exact shared scope"
            );

            for (label, item) in [
                ("scope seal", scope_seal),
                ("revocation planner", planner),
                ("executor binding", executor_binding),
            ] {
                assert!(
                    !item.contains("BusinessAuthorityGuard")
                        && !item.contains("G6BusinessAuthorityBinding")
                        && !item.contains("seal_g6_binding")
                        && !item.contains("locked_registration_from_guard"),
                    "G6 {label} must not accept or recover the raw business guard"
                );
            }
            assert!(
                !g6_source_code(core).contains("G6BusinessAuthorityBinding"),
                "the complete G6 repository prelude must be rooted in shared scope authority"
            );
            for (label, source) in [("core", core), ("execution", execution)] {
                let code = g6_source_code(source);
                assert!(
                    !code.contains("BusinessAuthorityGuard")
                        && !code.contains("G6BusinessAuthorityBinding"),
                    "G6 {label} must not expose a raw business-authority primitive"
                );
            }
            let production_witness = g6_source_code(g6_source_item(
                execution,
                "fn g6_scope_bound_production_pipeline_typecheck()",
            ));
            for stage in [
                "prepare_g6_identity_scope",
                "seal_g6_scope_authority",
                "lock_g6_revocation_prehead_scope",
                "LockedG6PreheadScope::seal_fanout",
                "hydrate_locked_g6_prelude",
                "HydrationAuthority::plan_device_revocation_batch",
                "prepare_canonical_device_revocation_batch_execution",
                "apply_device_revocation_batch_sequential",
            ] {
                assert!(
                    production_witness.contains(stage),
                    "production configuration omitted typed G6 stage: {stage}"
                );
            }

            let canonical = g6_source_code(g6_source_item(
                execution,
                "pub(crate) async fn prepare_canonical_device_revocation_batch_execution",
            ));
            let canonical_signature = canonical
                .split_once('{')
                .expect("canonical G6 wrapper has a body")
                .0;
            for required_input in [
                "transaction: &'transaction mut Transaction<'connection, Postgres>",
                "plan: &'plan DeviceRevocationBatchPersistencePlan",
                "prelude: LockedG6Prelude",
            ] {
                assert!(
                    canonical_signature.contains(required_input),
                    "canonical G6 wrapper omitted sealed input: {required_input}"
                );
            }
            for forbidden_input in [
                "ExecutionContextArtifacts",
                "ConversationExecutionArtifacts",
                "artifact_inputs",
                "event",
                "disposition",
                "bytes",
            ] {
                assert!(
                    !canonical_signature.contains(forbidden_input),
                    "canonical G6 wrapper accepts caller artifact input: {forbidden_input}"
                );
            }
            let canonical_compact = canonical.split_whitespace().collect::<Vec<_>>().join(" ");
            assert!(
                canonical_compact.contains("let artifact_inputs = plan .conversations() .iter()")
            );
            assert!(canonical_compact.contains(
                "ConversationExecutionArtifacts::new( Uuid::from_bytes(*conversation.state().coordinate.conversation_id()), ExecutionContextArtifacts::default(), )"
            ));
            assert_eq!(canonical_compact.matches(".collect();").count(), 1);
            assert_eq!(
                canonical
                    .matches("prepare_device_revocation_batch_execution")
                    .count(),
                1,
                "canonical G6 wrapper delegates exactly once"
            );
            assert!(canonical_compact.contains(
                "prepare_device_revocation_batch_execution(transaction, plan, prelude, artifact_inputs).await"
            ));
            for forbidden in ["BusinessAuthorityGuard", "G6BusinessAuthorityBinding"] {
                assert!(
                    !canonical.contains(forbidden),
                    "canonical G6 wrapper recovered raw authority: {forbidden}"
                );
            }
        }

        #[test]
        fn g6_capsule_binding_covers_prepared_plan_context_and_event_schedule() {
            let state_machine = include_str!("../src/chat_protocol/state_machine.rs");
            let execution = include_str!("../src/chat_protocol/repository/execution_context.rs");
            let member_digest_item = g6_source_item(
                state_machine,
                "fn prepared_device_revocation_members_binding_digest(",
            );
            let member_digest = g6_source_code(member_digest_item);
            for bound_projection in [
                "let plan_projection = format!(",
                "let member_projection = format!(",
                "cursor.initial_binding_digest()",
            ] {
                assert!(
                    member_digest.contains(bound_projection),
                    "prepared-member digest omitted {bound_projection}"
                );
            }
            let member_digest_literals = g6_source_literals(member_digest_item);
            assert!(member_digest_literals.contains("\"{plan:?}\""));
            assert!(member_digest_literals.contains("\"{member:?}\""));
            let cursor_digest = g6_source_code(g6_source_item(
                state_machine,
                "fn event_chain_cursor_binding_digest",
            ));
            for bound_projection in [
                "prelude_digest",
                "devices",
                "initial_tails",
                "schedule_len",
                "event.schedule_digest",
            ] {
                assert!(
                    cursor_digest.contains(bound_projection),
                    "event-chain cursor digest omitted {bound_projection}"
                );
            }
            let capsule_digest =
                g6_source_code(g6_source_item(execution, "fn g6_capsule_scope_binding("));
            assert!(capsule_digest.contains("prepared_members_digest"));
            let apply = g6_source_code(g6_source_item(
                execution,
                "pub(crate) async fn apply_device_revocation_batch_sequential(",
            ));
            let intact = apply
                .find("members.binding_is_intact()")
                .expect("capsule revalidates the complete prepared members");
            let prefix = apply
                .find("apply_prepared_device_revocation_prefix")
                .expect("capsule applies its immutable prefix");
            assert!(
                intact < prefix
                    && apply.contains("members.binding_digest() != &prepared_members_digest")
                    && apply.contains("&prepared_members_digest"),
                "capsule must compare its independent prepared-member binding before first write"
            );
        }

        #[test]
        fn g6_discovery_and_prehead_typestate_enforce_lock_order() {
            let core = include_str!("../src/chat_protocol/repository/core.rs");
            let discovery =
                g6_source_item(core, "pub(crate) async fn discover_g6_revocation_scope(");
            let discovery_code = g6_source_code(discovery);
            let discovery_literals = g6_source_literals(discovery);
            let discovery_upper = discovery_literals.to_ascii_uppercase();
            assert!(
                !discovery_upper.contains("FOR UPDATE") && !discovery_upper.contains("FOR SHARE"),
                "complete G6 discovery must remain read-only"
            );
            for required_source in [
                "chat.member_devices",
                "chat.leaf_recovery_requests",
                "chat.key_package_reservations",
                "chat.welcome_deliveries",
                "chat.recovery_work_items",
                "chat.participants",
                "chat.devices",
            ] {
                assert!(
                    discovery_literals.contains(required_source),
                    "G6 discovery omitted {required_source}"
                );
            }
            assert_eq!(
                discovery_code.matches("sqlx::query_as(").count(),
                1,
                "all discovery families must share one statement snapshot"
            );
            let identity = g6_source_item(core, "pub(crate) async fn prepare_g6_identity_scope(");
            let identity = g6_source_code(identity);
            let discovery_call = identity
                .find("discover_g6_revocation_scope")
                .expect("G6 identity facade performs discovery");
            let identity_locks = identity
                .find("prepare_identity_scope_prelude")
                .expect("G6 identity facade acquires canonical identity locks");
            assert!(
                discovery_call < identity_locks,
                "G6 discovery must complete before canonical identity locks"
            );

            let prehead = g6_source_item(
                core,
                "pub(crate) async fn lock_g6_revocation_prehead_scope(",
            );
            let prehead = g6_source_code(prehead);
            let packages = prehead
                .find("hydrate_locked_revocation_packages")
                .expect("pre-head stage locks target packages");
            let global = prehead
                .find("lock_g6_revocation_global_work")
                .expect("pre-head stage locks target-global work");
            assert!(packages < global);
            assert!(!prehead.contains("hydrate_locked_conversation"));

            let raw_scope_impl = g6_source_item(core, "impl LockedG6ScopeAuthority");
            let raw_scope_impl = g6_source_code(raw_scope_impl);
            assert!(
                !raw_scope_impl.contains("conversation_ids"),
                "conversation IDs must not escape before package/global locks"
            );
            let prehead_impl = g6_source_item(core, "impl LockedG6PreheadScope");
            let prehead_impl = g6_source_code(prehead_impl);
            assert!(prehead_impl.contains("fn conversation_ids"));
        }

        #[test]
        fn g6_post_head_path_has_no_identity_lock_or_identity_query() {
            let core = include_str!("../src/chat_protocol/repository/core.rs");
            let execution = include_str!("../src/chat_protocol/repository/execution_context.rs");

            let post_head = g6_source_item(core, "pub(crate) async fn hydrate_locked_g6_prelude(");
            let post_head_code = g6_source_code(post_head);
            let post_head_upper = g6_source_literals(post_head).to_ascii_uppercase();
            for forbidden in [
                "FROM CHAT.DEVICES",
                "JOIN CHAT.DEVICE_KEYS",
                "FOR UPDATE",
                "FOR SHARE",
            ] {
                assert!(
                    !post_head_upper.contains(forbidden),
                    "post-head G6 prelude contains forbidden identity access: {forbidden}"
                );
            }

            let actor = g6_source_item(execution, "fn g6_actor(");
            let event = g6_source_item(execution, "fn g6_event(");
            let scoped = g6_source_item(execution, "async fn hydrate_g6_execution_context_inner(");
            let batch = g6_source_item(execution, "async fn prepare_device_revocation_contexts(");
            let actor = g6_source_code(actor);
            let event = g6_source_code(event);
            let scoped = g6_source_code(scoped);
            let batch_code = g6_source_code(batch);
            let batch_sql = g6_source_literals(batch).to_ascii_uppercase();
            for (label, item) in [
                ("actor", actor.as_str()),
                ("event", event.as_str()),
                ("scoped wrapper", scoped.as_str()),
            ] {
                assert!(
                    !item.contains("sqlx::")
                        && !item.contains("lock_actor(")
                        && !item.contains("standard_audience(")
                        && !item.contains("event(transaction"),
                    "G6 {label} reintroduced post-head identity SQL"
                );
            }
            assert!(
                !batch_code.contains("lock_actor(")
                    && !batch_code.contains("standard_audience(")
                    && !batch_code.contains("event(transaction")
                    && !batch_sql.contains("FROM CHAT.DEVICES")
                    && !batch_sql.contains("JOIN CHAT.DEVICE_KEYS"),
                "G6 batch hydration reintroduced post-head identity access"
            );
            assert!(scoped.contains("Some(prelude)"));
            assert!(batch_code.contains("hydrate_g6_execution_context_inner"));
            assert!(!batch_code.contains("preflight_device_revocation_execution_authority"));

            let shared = g6_source_item(
                execution,
                "async fn hydrate_execution_context_inner_with_g6(",
            );
            let shared_code = g6_source_code(shared);
            let validator = shared_code
                .find("validate_g6_hydration_shape(plan, &artifacts)?")
                .expect("G6 shape validation is in the actual shared hydrator");
            let first_query = shared_code
                .find("sqlx::query_scalar")
                .expect("shared hydrator retains transaction identity query");
            assert!(
                validator < first_query,
                "G6 shape validation must precede every transaction query"
            );
            let shared_compact = g6_compact_code(shared);
            assert!(
                shared_compact.contains(
                    "let closing_leaf_periods = if g6_prelude.is_some() { Vec::new() } else"
                ),
                "actual shared G6 hydrator must bypass closing-leaf SQL"
            );
            let helper_bundle_declaration = shared_code
                .find("opened_leaves,")
                .expect("actual shared G6 hydrator declares the terminal helper bundle");
            let pure_bundle_start = shared_code[helper_bundle_declaration..]
                .find(") = if g6_prelude.is_some() {")
                .map(|offset| helper_bundle_declaration + offset)
                .expect("actual shared G6 hydrator has a pure terminal helper bundle");
            let pure_bundle_end = shared_code[pure_bundle_start..]
                .find("} else {")
                .map(|offset| pure_bundle_start + offset)
                .expect("actual shared G6 terminal helper bundle has a generic alternate");
            let pure_bundle = &shared_code[pure_bundle_start..pure_bundle_end];
            assert!(pure_bundle.contains("g6_spine_artifacts(plan)?"));
            for forbidden in [
                "opened_leaf_columns(",
                "participant_period_ids(",
                "closing_participant_periods(",
                "metadata_author(",
                "spine_artifacts(transaction",
                "recovery_open(",
            ] {
                assert!(
                    !pure_bundle.contains(forbidden),
                    "G6 pure helper bundle reached generic hydrator: {forbidden}"
                );
            }
            let shape_gate =
                g6_source_code(g6_source_item(execution, "fn validate_g6_hydration_shape("));
            let spine = g6_source_code(g6_source_item(execution, "fn g6_spine_artifacts("));
            for (label, code) in [
                ("shape gate", shape_gate.as_str()),
                ("actor", actor.as_str()),
                ("event", event.as_str()),
                ("spine", spine.as_str()),
            ] {
                assert!(
                    !code.contains("sqlx::")
                        && !code.contains("lock_actor(")
                        && !code.contains("actor_role(")
                        && !code.contains("standard_audience(")
                        && !code.contains("historical_schedule_audience("),
                    "G6 {label} must remain a pure sealed-projection helper"
                );
            }
            assert!(
                !post_head_code.contains("BusinessAuthorityGuard"),
                "post-head repository hydration must consume only sealed G6 projections"
            );
        }

        #[test]
        fn g6_locked_prelude_digest_binds_shared_authority_scope() {
            let actor_did = "did:plc:aaaaaaaaaaaaaaaaaaaaaaaa".to_owned();
            let actor_device_id = Uuid::new_v4();
            let actor = DeviceIdentity::new(
                PrincipalId::new(actor_did.as_bytes().to_vec()).expect("test principal"),
                *actor_device_id.as_bytes(),
            )
            .expect("test device");
            let conversation_id = Uuid::new_v4();
            let trusted_instant = DateTime::parse_from_rfc3339("2026-07-28T12:00:00.000Z")
                .expect("fixed test instant")
                .with_timezone(&Utc);
            let make = |authority_scope_digest| {
                LockedG6Prelude::for_test(
                    "424242".to_owned(),
                    trusted_instant,
                    authority_scope_digest,
                    actor_did.clone(),
                    actor_device_id,
                    "g6-dpop-jkt".to_owned(),
                    1,
                    "g6-key-id".to_owned(),
                    vec![7; 32],
                    actor_did.clone(),
                    actor_device_id,
                    1,
                    vec![conversation_id],
                    vec![[8; 32]],
                    vec![(actor.clone(), "g6-dpop-jkt".to_owned(), 1, Some(9))],
                    [10; 32],
                )
            };
            let first = make([1; 32]);
            let second = make([2; 32]);
            assert_ne!(
                first.authority_scope_digest(),
                second.authority_scope_digest()
            );
            assert_ne!(first.scope_digest(), second.scope_digest());
        }

        #[test]
        fn g6_prelude_binding_rejects_foreign_shared_scope_without_sql() {
            let actor_did = "did:plc:aaaaaaaaaaaaaaaaaaaaaaaa".to_owned();
            let actor_device_id = Uuid::new_v4();
            let actor = DeviceIdentity::new(
                PrincipalId::new(actor_did.as_bytes().to_vec()).expect("canonical actor DID"),
                *actor_device_id.as_bytes(),
            )
            .expect("canonical actor device");
            let accepted_at = DateTime::parse_from_rfc3339("2026-07-28T12:00:00.000Z")
                .expect("fixed G6 binding instant")
                .with_timezone(&Utc);
            let accepted =
                ServerTimestamp::from_unix_millis_for_test(accepted_at.timestamp_millis())
                    .expect("canonical G6 binding instant");
            let evidence = DeviceRevocationEvidence::for_test(
                *Uuid::new_v4().as_bytes(),
                actor.clone(),
                actor.clone(),
                [3; 32],
                1,
                1,
                accepted,
                accepted,
                [4; 32],
                [5; 64],
                vec![6],
                vec![7],
            );
            let plan = DeviceRevocationBatchPersistencePlan::for_test(
                evidence,
                RevocationTargetCasBinding::for_test_with_transaction_id(
                    "424242".to_owned(),
                    actor.clone(),
                    1,
                    accepted,
                ),
                Vec::new(),
                Vec::new(),
            );
            let prelude = |authority_scope_digest| {
                LockedG6Prelude::for_test(
                    "424242".to_owned(),
                    accepted_at,
                    authority_scope_digest,
                    actor_did.clone(),
                    actor_device_id,
                    "g6-dpop-jkt".to_owned(),
                    1,
                    URL_SAFE_NO_PAD.encode([3; 32]),
                    vec![8; 32],
                    actor_did.clone(),
                    actor_device_id,
                    1,
                    Vec::new(),
                    Vec::new(),
                    vec![(actor.clone(), "g6-dpop-jkt".to_owned(), 1, None)],
                    [1; 32],
                )
            };
            assert!(
                validate_g6_prelude_binding(&plan, &prelude([1; 32])).is_ok(),
                "the exact shared scope must bind without touching PostgreSQL"
            );
            assert!(matches!(
                validate_g6_prelude_binding(&plan, &prelude([2; 32])),
                Err(SequentialDeviceRevocationError::PreludeMismatch)
            ));
        }

        #[test]
        fn g6_package_completeness_rejects_a_proper_subset() {
            let first = LockedRevocationPackageGuard::for_g6_completeness_test(
                [1; 32],
                LockedRecoveryPackageStatus::Available,
                None,
                None,
            );
            let second = LockedRevocationPackageGuard::for_g6_completeness_test(
                [2; 32],
                LockedRecoveryPackageStatus::Available,
                None,
                None,
            );
            let manifests = vec![
                first.manifest_for_g6_completeness_test(),
                second.manifest_for_g6_completeness_test(),
            ];
            let packages = vec![first, second];
            assert!(locked_revocation_packages_match_fanout_for_test(
                &packages, &manifests
            ));
            assert!(
                !locked_revocation_packages_match_fanout_for_test(&packages[..1], &manifests),
                "a caller-selected proper subset cannot satisfy the complete fanout manifest"
            );
            assert!(
                !locked_revocation_packages_match_fanout_for_test(&packages, &manifests[..1]),
                "a truncated manifest cannot authenticate the complete locked package set"
            );
        }

        #[derive(Clone, Copy)]
        struct CreationRelationshipTransport;

        static CREATION_RELATIONSHIP_CALLS: AtomicUsize = AtomicUsize::new(0);

        fn query_values(url: &Url, key: &str) -> Vec<String> {
            url.query_pairs()
                .filter(|(name, _)| name == key)
                .map(|(_, value)| value.into_owned())
                .collect()
        }

        #[async_trait]
        impl PublicTransport for CreationRelationshipTransport {
            async fn get(&self, request: PublicGet) -> Result<PublicResponse, TransportError> {
                CREATION_RELATIONSHIP_CALLS.fetch_add(1, AtomicOrdering::SeqCst);
                let path = request.url.path();
                if path.starts_with("/did:plc:") {
                    let actor = path.trim_start_matches('/');
                    return Ok(PublicResponse::json(
                        200,
                        json!({
                            "id": actor,
                            "service": [{
                                "id": format!("{actor}#atproto_pds"),
                                "type": "AtprotoPersonalDataServer",
                                "serviceEndpoint": "https://pds.example.net",
                            }],
                        }),
                    ));
                }
                if path == "/xrpc/com.atproto.repo.getRecord" {
                    let actor = query_values(&request.url, "repo")
                        .into_iter()
                        .next()
                        .expect("relationship record repo");
                    return Ok(PublicResponse::json(
                        200,
                        json!({
                            "uri": format!("at://{actor}/chat.bsky.actor.declaration/self"),
                            "cid": "bafyreihdwdcefgh4dqkjv67uzcmw7ojee6xedzdetojuzjevtenxquvyku",
                            "value": {
                                "$type": "chat.bsky.actor.declaration",
                                "allowIncoming": "following",
                                "allowGroupInvites": "following",
                            },
                        }),
                    ));
                }
                if path == "/xrpc/app.bsky.graph.getRelationships" {
                    let actor = query_values(&request.url, "actor")
                        .into_iter()
                        .next()
                        .expect("relationship actor");
                    let relationships = query_values(&request.url, "others")
                        .into_iter()
                        .map(|did| {
                            json!({
                                "$type": "app.bsky.graph.defs#relationship",
                                "did": did,
                                "following": format!(
                                    "at://{actor}/app.bsky.graph.follow/g6creation"
                                ),
                            })
                        })
                        .collect::<Vec<_>>();
                    return Ok(PublicResponse::json(
                        200,
                        json!({"actor": actor, "relationships": relationships}),
                    ));
                }
                panic!("unexpected relationship request: {}", request.url);
            }
        }

        #[derive(Clone, Copy)]
        struct FixedProjectionClock(DateTime<Utc>);

        impl ProjectionClock for FixedProjectionClock {
            fn now(&self) -> DateTime<Utc> {
                self.0
            }
        }

        // Fixed millisecond instants (the state machine's `CanonicalTimestamp`
        // grammar is `...T...Z` at millisecond precision, which round-trips
        // losslessly through Postgres microsecond storage). `EXPIRES_AT` is
        // exactly `LEAST(REQUESTED_AT + 5min, KP.not_after)`, the expiry the
        // deferred `assert_recovery_fulfillment_mapping` constraint requires.
        const KP_NOT_BEFORE: &str = "2026-07-27T03:05:08.000Z";
        const KP_NOT_AFTER: &str = "2026-07-28T03:06:08.000Z";
        const CREATION_SIGNED_AT: &str = "2026-07-27T03:06:08.000Z";
        const CREATION_RECEIVED_AT: &str = "2026-07-27T03:06:09.000Z";
        const POLICY_ADD_AT: &str = "2026-07-27T04:06:08.000Z";
        const SIGNED_AT: &str = "2026-07-27T04:06:08.500Z";
        const REQUESTED_AT: &str = "2026-07-27T04:06:09.000Z";
        const EXPIRES_AT: &str = "2026-07-27T04:11:09.000Z";
        const FULFILLMENT_SIGNED_AT: &str = "2026-07-27T04:06:09.500Z";
        const FULFILLED_AT: &str = "2026-07-27T04:06:10.000Z";
        const GENERIC_SIGNED_AT: &str = "2026-07-27T04:06:10.500Z";
        const GENERIC_AT: &str = "2026-07-27T04:06:11.000Z";
        const LEAVE_SIGNED_AT: &str = "2026-07-27T04:06:11.500Z";
        const LEAVE_AT: &str = "2026-07-27T04:06:12.000Z";
        const LEAVE_FULFILLMENT_SIGNED_AT: &str = "2026-07-27T04:06:12.500Z";
        const LEAVE_FULFILLED_AT: &str = "2026-07-27T04:06:13.000Z";
        const REINVITE_AT: &str = "2026-07-27T04:06:14.000Z";
        const REACCEPT_SIGNED_AT: &str = "2026-07-27T04:06:14.500Z";
        const REACCEPT_AT: &str = "2026-07-27T04:06:15.000Z";
        const REACCEPT_EXPIRES_AT: &str = "2026-07-27T04:11:15.000Z";
        const REJOIN_SIGNED_AT: &str = "2026-07-27T04:06:15.500Z";
        const REJOIN_AT: &str = "2026-07-27T04:06:16.000Z";
        const ROLE_ADMIN_AT: &str = "2026-07-27T04:06:11.000Z";
        const ROLE_MEMBER_AT: &str = "2026-07-27T04:06:12.000Z";

        async fn g6_gate_pool(label: &str) -> PgPool {
            const FIXED_GATE_DB: &str =
                "postgresql://127.0.0.1:5432/catbird_chat_protocol_test_20260722";
            let database_url = std::env::var("TEST_DATABASE_URL")
                .expect("TEST_DATABASE_URL must name the existing gate database");
            assert_eq!(
                database_url, FIXED_GATE_DB,
                "G6 {label} may write only its dedicated append-only database"
            );
            common::chat_protocol::validate_chat_protocol_database_url(Some(&database_url))
                .unwrap_or_else(|_| panic!("unsafe TEST_DATABASE_URL for G6 {label}"));
            PgPool::connect(&database_url)
                .await
                .unwrap_or_else(|error| panic!("connect to G6 gate database for {label}: {error}"))
        }

        const BOB_SIGNING_SEED: [u8; 32] = [
            0xd4, 0xa1, 0xc4, 0x8e, 0x33, 0x92, 0x40, 0x8e, 0x24, 0x40, 0x90, 0x3f, 0xc5, 0x67,
            0x8d, 0xa5, 0x69, 0x98, 0xeb, 0x66, 0xeb, 0xb8, 0xa9, 0x64, 0xa7, 0xe4, 0xe4, 0xc2,
            0xad, 0x82, 0xe9, 0xb5,
        ];

        #[tokio::test]
        #[ignore = "requires the dedicated gate database"]
        async fn genuine_multi_participant_policy_role_aggregate_seal() {
            let database_url = std::env::var("TEST_DATABASE_URL")
                .expect("TEST_DATABASE_URL must name the existing gate database");
            common::chat_protocol::validate_chat_protocol_database_url(Some(&database_url))
                .expect("unsafe TEST_DATABASE_URL for genuine role aggregate");
            let pool = PgPool::connect(&database_url)
                .await
                .expect("connect to existing gate database");

            let corpus_key_package_ref = validate_exact_corpus_recovery_artifacts();
            let manifest = corpus_manifest();
            let evolved_cid =
                Uuid::parse_str(manifest["identifiers"]["conversationId"].as_str().unwrap())
                    .unwrap();
            if let Some(committed) =
                find_committed_exact_corpus_graph(&pool, corpus_key_package_ref, evolved_cid).await
            {
                match (committed.state_version, committed.next_entry_seq) {
                    (5, 7) => assert_committed_exact_corpus_graph(&pool, &committed).await,
                    (8, 11) => {
                        assert_eq!(committed.cid, evolved_cid);
                        assert_terminal_family_b_final_graph(&pool, committed.cid).await;
                    }
                    head => panic!("unrecognized exact-corpus reusable head: {head:?}"),
                }
                return;
            }
            let corpus_ref_occupied: bool = sqlx::query_scalar(
                "SELECT EXISTS(SELECT 1 FROM chat.key_packages WHERE key_package_ref=$1)",
            )
            .bind(corpus_key_package_ref.to_vec())
            .fetch_one(&pool)
            .await
            .expect("check exact corpus KeyPackageRef occupancy");
            assert!(
                !corpus_ref_occupied,
                "exact corpus KeyPackageRef already exists without a complete reusable graph; \
                 the append-only gate requires a fresh database"
            );

            let graph = commit_genuine_policy_acceptance_fulfillment(&pool).await;
            let first = execute_genuine_role_change(
                &pool,
                &graph,
                &graph.invitee.did,
                ParticipantRole::Admin,
                5,
                ROLE_ADMIN_AT,
                Some(graph.fulfillment.welcome_id),
                true,
            )
            .await;
            assert_eq!(first.coordinate().state_version(), 4);
            let second = execute_genuine_role_change(
                &pool,
                &graph,
                &graph.invitee.did,
                ParticipantRole::Member,
                6,
                ROLE_MEMBER_AT,
                None,
                true,
            )
            .await;
            assert_eq!(second.coordinate().state_version(), 5);

            let cid = Uuid::from_bytes(graph.entry.cid);
            let locked_at: DateTime<Utc> =
                sqlx::query_scalar("SELECT date_trunc('milliseconds', clock_timestamp())")
                    .fetch_one(&pool)
                    .await
                    .expect("canonical aggregate lock instant");
            let mut tx = pool.begin().await.expect("begin final aggregate read");
            let aggregate = hydrate_locked_conversation_state(&mut tx, cid, locked_at)
                .await
                .expect("genuine multi-participant aggregate seals");
            let bob = PrincipalId::new(graph.invitee.did.as_bytes().to_vec()).unwrap();
            let participant = aggregate
                .state()
                .participant(&bob)
                .expect("Bob remains a participant");
            assert_eq!(participant.status(), ParticipantStatus::Active);
            assert_eq!(participant.role(), ParticipantRole::Member);
            assert_eq!(aggregate.state().participants().len(), 2);
            assert_eq!(aggregate.state().leaves().len(), 2);
            assert_eq!(aggregate.state().intervals().len(), 2);
            let recovery = aggregate
                .state()
                .recovery_request(&graph.acceptance.request_id)
                .expect("acceptance recovery retained");
            assert_eq!(recovery.status(), RecoveryRequestStatus::Fulfilled);
            let reservation = aggregate
                .state()
                .recovery_reservation(&graph.acceptance.request_id)
                .expect("acceptance reservation retained");
            assert_eq!(reservation.status(), ReservationStatus::Consumed);
            let welcome = aggregate
                .state()
                .welcome(graph.fulfillment.welcome_id.as_bytes())
                .expect("Welcome retained");
            assert_eq!(welcome.status(), WelcomeStatus::Superseded);
            let durable_provenance: (i64, i64, i64, i64, i64, String, Option<Uuid>) =
                sqlx::query_as(
                    r#"
                SELECT invitation.entry_seq,
                       acceptance.entry_seq,
                       role.entry_seq,
                       producer.entry_seq,
                       metadata_producer.entry_seq,
                       delivery.status,
                       disposition.terminal_transition_id
                  FROM chat.participants participant
                  JOIN chat.transitions invitation
                    ON invitation.transition_id=participant.invitation_transition_id
                  JOIN chat.transitions acceptance
                    ON acceptance.transition_id=participant.acceptance_transition_id
                  JOIN chat.transitions role
                    ON role.transition_id=participant.role_transition_id
                  JOIN chat.generation_states state
                    ON state.conversation_id=participant.conversation_id
                   AND state.generation=0 AND state.state_version=5
                  JOIN chat.transitions producer
                    ON producer.transition_id=state.producing_transition_id
                  JOIN chat.metadata_snapshots metadata
                    ON metadata.conversation_id=participant.conversation_id
                   AND metadata.generation=0
                   AND metadata.state_version=3
                  JOIN chat.transitions metadata_producer
                    ON metadata_producer.transition_id=metadata.producing_transition_id
                  JOIN chat.welcome_deliveries delivery
                    ON delivery.welcome_id=$3
                  JOIN chat.welcome_dispositions disposition
                    ON disposition.welcome_id=delivery.welcome_id
                 WHERE participant.conversation_id=$1
                   AND participant.user_did=$2
                   AND participant.current_membership
                "#,
                )
                .bind(cid)
                .bind(&graph.invitee.did)
                .bind(graph.fulfillment.welcome_id)
                .fetch_one(&mut *tx)
                .await
                .expect("durable provenance remains populated");
            assert_eq!(durable_provenance.0, 2, "Bob invitation producer");
            assert_eq!(durable_provenance.1, 3, "Bob acceptance producer");
            assert_eq!(durable_provenance.2, 6, "Bob latest role producer");
            assert_eq!(durable_provenance.3, 6, "current state producer");
            assert_eq!(durable_provenance.4, 4, "retained metadata producer");
            assert_eq!(durable_provenance.5, "superseded");
            let welcome_terminal = durable_provenance
                .6
                .expect("Welcome transition terminal populated");
            let welcome_terminal_seq: i64 =
                sqlx::query_scalar("SELECT entry_seq FROM chat.transitions WHERE transition_id=$1")
                    .bind(welcome_terminal)
                    .fetch_one(&mut *tx)
                    .await
                    .expect("Welcome terminal seq");
            assert_eq!(welcome_terminal_seq, 5);
            let recovery_terminal_seqs: (i64, i64) = sqlx::query_as(
                r#"
                SELECT request_terminal.entry_seq,reservation_terminal.entry_seq
                  FROM chat.leaf_recovery_requests request
                  JOIN chat.transitions request_terminal
                    ON request_terminal.transition_id=request.fulfilling_transition_id
                  JOIN chat.key_package_reservations reservation
                    ON reservation.recovery_request_id=request.recovery_request_id
                  JOIN chat.transitions reservation_terminal
                    ON reservation_terminal.transition_id=reservation.consumed_transition_id
                 WHERE request.recovery_request_id=$1
                "#,
            )
            .bind(Uuid::from_bytes(graph.acceptance.request_id))
            .fetch_one(&mut *tx)
            .await
            .expect("recovery work terminals populated");
            assert_eq!(recovery_terminal_seqs, (4, 4));
            let durable_add_artifacts: (i64, i64, String, i64) = sqlx::query_as(
                r#"
                SELECT leaf.joined_seq,
                       interval.start_seq,
                       package.status,
                       package_terminal.entry_seq
                  FROM chat.member_devices leaf
                  JOIN chat.application_intervals interval
                    ON interval.opening_leaf_period_id=leaf.leaf_period_id
                  JOIN chat.key_packages package
                    ON package.key_package_ref=leaf.join_key_package_ref
                  JOIN chat.transitions package_terminal
                    ON package_terminal.transition_id=package.terminal_transition_id
                 WHERE leaf.conversation_id=$1
                   AND leaf.user_did=$2
                   AND leaf.device_id=$3
                   AND leaf.active
                   AND interval.terminal_seq IS NULL
                "#,
            )
            .bind(cid)
            .bind(&graph.invitee.did)
            .bind(graph.invitee.device_id)
            .fetch_one(&mut *tx)
            .await
            .expect("Bob Add leaf, interval, and package remain exact");
            assert_eq!(
                durable_add_artifacts,
                (4, 4, "consumed".to_owned(), 4),
                "Add fulfillment opens Bob at seq 4 and consumes the package at seq 4"
            );
            assert_eq!(aggregate.state().coordinate().state_version(), 5);
            assert_eq!(aggregate.head().next_entry_seq(), 7);
            assert_ne!(aggregate.locked_graph_digest(), &[0; 32]);
            let first_digest = *aggregate.locked_graph_digest();
            tx.rollback()
                .await
                .expect("rollback read-only final aggregate");

            let fresh_locked_at = locked_at + chrono::Duration::milliseconds(1);
            let mut fresh = pool.begin().await.expect("begin fresh aggregate read");
            let reloaded = hydrate_locked_conversation_state(&mut fresh, cid, fresh_locked_at)
                .await
                .expect("fresh transaction reseals identical graph");
            assert_eq!(reloaded.locked_graph_digest(), &first_digest);
            fresh
                .rollback()
                .await
                .expect("rollback fresh aggregate read");
        }

        struct G6RevocationPreflightFixture {
            evidence: DeviceRevocationEvidence,
            target_cas: RevocationTargetCasBinding,
            conversation_plan: ConversationPersistencePlan,
            conversation_state: ConversationState,
            context: ExecutionContext,
            target_did: String,
            target_device_id: Uuid,
            target_key_id: String,
            revocation_id: Uuid,
            accepted_at: DateTime<Utc>,
        }

        impl G6RevocationPreflightFixture {
            fn conversation_plan_for_transaction(
                &self,
                transaction_id: &str,
            ) -> ConversationPersistencePlan {
                let planned =
                    plan_device_revocation(&self.conversation_state, self.evidence.clone())
                        .expect("genuine revocation replans for exact transaction packaging");
                let template_head = self
                    .conversation_plan
                    .effects()
                    .head_cas()
                    .expect("fixture retains its synthesized head CAS");
                device_revocation_plan_for_test(
                    planned,
                    ConversationHeadCasBinding::for_test_internal_with_transaction_id(
                        transaction_id.to_owned(),
                        *template_head.conversation_id(),
                        *self.conversation_state.coordinate(),
                        template_head.expected_next_entry_seq(),
                        template_head.locked_at(),
                    ),
                    self.evidence.clone(),
                )
            }

            fn batch(
                &self,
                revoked_packages: Vec<RevocationPackageCasBinding>,
                conversations: Vec<ConversationPersistencePlan>,
            ) -> DeviceRevocationBatchPersistencePlan {
                DeviceRevocationBatchPersistencePlan::for_test(
                    self.evidence.clone(),
                    self.target_cas.clone(),
                    revoked_packages,
                    conversations,
                )
            }
        }

        async fn g6_revocation_preflight_fixture(
            pool: &PgPool,
        ) -> (GenuinePolicyRoleGraph, G6RevocationPreflightFixture) {
            let graph = commit_genuine_policy_acceptance_fulfillment_at(
                pool,
                Uuid::new_v4(),
                Uuid::new_v4(),
            )
            .await;
            g6_revocation_preflight_fixture_for_graph(pool, graph).await
        }

        async fn g6_revocation_preflight_fixture_for_graph(
            pool: &PgPool,
            graph: GenuinePolicyRoleGraph,
        ) -> (GenuinePolicyRoleGraph, G6RevocationPreflightFixture) {
            let target = DeviceIdentity::new(
                PrincipalId::new(graph.invitee.did.as_bytes().to_vec())
                    .expect("canonical target DID"),
                *graph.invitee.device_id.as_bytes(),
            )
            .expect("canonical target device");
            let actor_key_id: [u8; 32] = URL_SAFE_NO_PAD
                .decode(&graph.invitee.key_id)
                .expect("decode target key id")
                .try_into()
                .expect("Ed25519 key id");
            let accepted_at: DateTime<Utc> =
                sqlx::query_scalar("SELECT date_trunc('milliseconds', clock_timestamp())")
                    .fetch_one(pool)
                    .await
                    .expect("sample revocation instant");
            let accepted =
                ServerTimestamp::from_unix_millis_for_test(accepted_at.timestamp_millis())
                    .expect("canonical revocation instant");
            let cid = Uuid::from_bytes(graph.entry.cid);
            let mut read = pool.begin().await.expect("begin revocation aggregate read");
            let locked = hydrate_locked_conversation_state(&mut read, cid, accepted_at)
                .await
                .expect("hydrate genuine revocation aggregate");
            let conversation_state = locked.state().clone();
            read.rollback()
                .await
                .expect("rollback revocation aggregate read");
            let revocation_id = Uuid::new_v4();
            let signed_at = accepted_at.to_rfc3339_opts(chrono::SecondsFormat::Millis, true);
            let body = json!({
                "$type": SignedMutationKind::DeviceRevocation.type_id(),
                "signatureDomain":
                    String::from_utf8(SignedMutationKind::DeviceRevocation.domain().to_vec())
                        .expect("revocation signature domain is UTF-8"),
                "actorDid": &graph.invitee.did,
                "actorDeviceId": graph.invitee.device_id.hyphenated().to_string(),
                "keyId": &graph.invitee.key_id,
                "authGeneration": 1,
                "targetDeviceId": graph.invitee.device_id.hyphenated().to_string(),
                "targetAuthGeneration": 1,
                "idempotencyKey": revocation_id.hyphenated().to_string(),
                "signedAt": signed_at,
            });
            let mut wrapper = json!({
                "body": body,
                "signature": STANDARD.encode([0_u8; 64]),
            });
            let unsigned = decode_canonical_signed_mutation(
                &serde_json::to_vec(&wrapper).expect("encode unsigned revocation"),
            )
            .expect("canonicalize genuine revocation");
            let signing_transcript = unsigned.transcript_bytes().to_vec();
            let signature = graph
                .invitee
                .signing_key
                .sign(&signing_transcript)
                .to_bytes();
            wrapper["signature"] = Value::String(STANDARD.encode(signature));
            let signed_request = serde_json::to_vec(&wrapper).expect("encode signed revocation");
            decode_and_verify_signed_mutation(
                &signed_request,
                graph.invitee.signing_key.verifying_key().as_bytes(),
            )
            .expect("genuine revocation verifies");
            let request_digest: [u8; 32] = Sha256::digest(&signing_transcript).into();
            let evidence = DeviceRevocationEvidence::for_test(
                *revocation_id.as_bytes(),
                target.clone(),
                target.clone(),
                actor_key_id,
                1,
                1,
                accepted,
                accepted,
                request_digest,
                signature,
                signed_request,
                signing_transcript,
            );
            let planned = plan_device_revocation(&conversation_state, evidence.clone())
                .expect("genuine active target plans revocation");
            let conversation_plan = device_revocation_plan_for_test(
                planned,
                ConversationHeadCasBinding::for_test_internal(
                    *cid.as_bytes(),
                    *conversation_state.coordinate(),
                    5,
                    accepted,
                ),
                evidence.clone(),
            );
            let protocol_instance_id: Uuid =
                sqlx::query_scalar("SELECT protocol_instance_id FROM chat.protocol_instances")
                    .fetch_one(pool)
                    .await
                    .expect("read protocol instance");
            let context = ExecutionContext {
                protocol_instance_id,
                applied_at: accepted_at,
                actor: ExecutionActor {
                    user_did: graph.invitee.did.clone(),
                    device_id: graph.invitee.device_id,
                    key_id: graph.invitee.key_id.clone(),
                    auth_generation: 1,
                    role: TransitionActorRole::Member,
                    device_status: "active".to_owned(),
                },
                authority: ExecutionAuthority::Entryless {
                    operation_id: revocation_id,
                },
                spine: SpineArtifacts {
                    public_snapshot_bytes: Vec::new(),
                    public_snapshot_sha256: Vec::new(),
                    tree_summary_bytes: Vec::new(),
                    tree_summary_sha256: Vec::new(),
                    leaf_count: 2,
                    genesis_group_info_bytes: Vec::new(),
                    genesis_group_info_sha256: Vec::new(),
                },
                opened_leaves: Vec::new(),
                metadata_author: None,
                metadata_avatar: None,
                participant_period_ids: Vec::new(),
                leaf_period_ids: Vec::new(),
                entry_recipients: Vec::new(),
                events: Vec::new(),
                closing_leaf_periods: Vec::new(),
                closing_participant_periods: Vec::new(),
                reset_request_row: None,
                recovery_open: None,
                welcome_expiry: None,
                welcome_response: None,
                welcome_dispositions: Vec::new(),
            };
            let target_cas = RevocationTargetCasBinding::for_test(target.clone(), 1, accepted);
            let target_did = graph.invitee.did.clone();
            let target_key_id = graph.invitee.key_id.clone();
            (
                graph,
                G6RevocationPreflightFixture {
                    evidence,
                    target_cas,
                    conversation_plan,
                    conversation_state,
                    context,
                    target_did,
                    target_device_id: Uuid::from_bytes(*target.device_id()),
                    target_key_id,
                    revocation_id,
                    accepted_at,
                },
            )
        }

        fn g6_control_authority(operation_id: Uuid) -> ExecutionAuthority {
            ExecutionAuthority::ControlEntry(ControlEntryContent {
                entry_id: operation_id,
                entry_kind: "blue.catbird.chat.defs#policyEntry".to_owned(),
                accepted_payload_bytes: vec![0xD1],
                accepted_payload_sha256: vec![0xD2; 32],
                signed_request_bytes: vec![0xD3],
                unsigned_projection_bytes: vec![0xD4],
                signing_transcript_bytes: vec![0xD5],
                request_digest: vec![0xD6; 32],
                signature: vec![0xD7; 64],
                server_fields_bytes: vec![0xD8],
                outer_entry_fingerprint: vec![0xD9; 32],
            })
        }

        async fn assert_g6_batch_preflight_left_no_writes(
            transaction: &mut Transaction<'_, Postgres>,
            fixture: &G6RevocationPreflightFixture,
            available_ref: Option<[u8; 32]>,
        ) {
            let revocations: i64 = sqlx::query_scalar(
                "SELECT count(*) FROM chat.device_revocations WHERE revocation_id=$1",
            )
            .bind(fixture.revocation_id)
            .fetch_one(&mut **transaction)
            .await
            .expect("count revocation residue");
            assert_eq!(
                revocations, 0,
                "invalid batch inserted its immutable revocation row"
            );
            let registration: (String, Option<Uuid>) = sqlx::query_as(
                "SELECT status,revocation_id FROM chat.devices \
                 WHERE user_did=$1 AND device_id=$2",
            )
            .bind(&fixture.target_did)
            .bind(fixture.target_device_id)
            .fetch_one(&mut **transaction)
            .await
            .expect("read target registration");
            assert_eq!(
                registration,
                ("active".to_owned(), None),
                "invalid batch changed the target registration"
            );
            if let Some(key_package_ref) = available_ref {
                let package: (String, Option<Uuid>) = sqlx::query_as(
                    "SELECT status,terminal_revocation_id FROM chat.key_packages \
                     WHERE key_package_ref=$1",
                )
                .bind(key_package_ref.to_vec())
                .fetch_one(&mut **transaction)
                .await
                .expect("read available package");
                assert_eq!(
                    package,
                    ("available".to_owned(), None),
                    "invalid batch revoked an available package"
                );
            }
        }

        async fn seed_g6_revoke_receipt(
            transaction: &mut Transaction<'_, Postgres>,
            fixture: &G6RevocationPreflightFixture,
        ) {
            let response_bytes = b"g6-sequential-revocation-ok".to_vec();
            sqlx::query(
                r#"
                INSERT INTO chat.operation_claims(
                    operation_id,principal_did,endpoint_nsid,mutation_kind,
                    request_digest,accepted_request_sha256,signature,claimed_at
                ) VALUES(
                    $1,$2,'blue.catbird.chat.revokeDevice',
                    'blue.catbird.chat.defs#deviceRevocationBody',$3,$4,$5,$6
                )
                "#,
            )
            .bind(fixture.revocation_id)
            .bind(&fixture.target_did)
            .bind(fixture.evidence.request_digest().to_vec())
            .bind(Sha256::digest(fixture.evidence.signed_request_bytes()).to_vec())
            .bind(fixture.evidence.signature().to_vec())
            .bind(fixture.accepted_at)
            .execute(&mut **transaction)
            .await
            .expect("seed exact revokeDevice operation claim before receipt");
            sqlx::query(
                r#"
                INSERT INTO chat.idempotency_records(
                    principal_did,endpoint_nsid,operation_id,request_digest,
                    accepted_request_bytes,signing_transcript_bytes,signature,
                    completed_status,response_bytes,response_sha256,event_position,
                    historical_jkt,current_jkt,completed_at
                ) VALUES($1,'blue.catbird.chat.revokeDevice',$2,$3,$4,$5,$6,200,
                    $7,$8,NULL,$9,NULL,$10)
                "#,
            )
            .bind(&fixture.target_did)
            .bind(fixture.revocation_id)
            .bind(fixture.evidence.request_digest().to_vec())
            .bind(fixture.evidence.signed_request_bytes().to_vec())
            .bind(fixture.evidence.signing_transcript_bytes().to_vec())
            .bind(fixture.evidence.signature().to_vec())
            .bind(&response_bytes)
            .bind(Sha256::digest(&response_bytes).to_vec())
            .bind(&fixture.target_key_id)
            .bind(fixture.accepted_at)
            .execute(&mut **transaction)
            .await
            .expect("seed caller-owned revokeDevice receipt");
        }

        async fn append_g6_available_package(
            pool: &PgPool,
            fixture: &G6RevocationPreflightFixture,
        ) -> ([u8; 32], RevocationPackageCasBinding) {
            let key_package_ref: [u8; 32] = Sha256::digest(Uuid::new_v4().as_bytes()).into();
            let created_at = fixture.accepted_at - chrono::Duration::hours(1);
            let wrapper = Uuid::new_v4().as_bytes().to_vec();
            let mut init_key = Uuid::new_v4().as_bytes().to_vec();
            init_key.extend_from_slice(Uuid::new_v4().as_bytes());
            sqlx::query(
                "INSERT INTO chat.key_packages(\
                    key_package_ref,wrapper_bytes,wrapper_sha256,init_key,owner_did,\
                    owner_device_id,owner_key_id,owner_auth_generation,not_before,not_after,\
                    status,created_at\
                 ) VALUES($1,$2,$3,$4,$5,$6,$7,1,$8,$9,'available',$10)",
            )
            .bind(key_package_ref.to_vec())
            .bind(&wrapper)
            .bind(Sha256::digest(&wrapper).to_vec())
            .bind(&init_key)
            .bind(&fixture.target_did)
            .bind(fixture.target_device_id)
            .bind(&fixture.target_key_id)
            .bind(created_at - chrono::Duration::hours(1))
            .bind(created_at + chrono::Duration::hours(24))
            .bind(created_at)
            .execute(pool)
            .await
            .expect("append unique available package");
            let accepted =
                ServerTimestamp::from_unix_millis_for_test(fixture.accepted_at.timestamp_millis())
                    .expect("canonical package revocation instant");
            (
                key_package_ref,
                RevocationPackageCasBinding::for_test_available(
                    fixture.evidence.target().clone(),
                    key_package_ref,
                    *fixture.revocation_id.as_bytes(),
                    accepted,
                ),
            )
        }

        fn g6_policy_plan(
            graph: &GenuinePolicyRoleGraph,
            prior: &ConversationState,
        ) -> (ConversationPersistencePlan, ExecutionContext) {
            let cid = Uuid::from_bytes(graph.entry.cid);
            let control = genuine_policy_control(
                &graph.entry,
                prior.coordinate(),
                5,
                ROLE_ADMIN_AT,
                vec![GenuinePolicyChange::ChangeRole(
                    &graph.invitee.did,
                    ParticipantRole::Admin,
                )],
            );
            let actor = DeviceIdentity::new(
                PrincipalId::new(graph.entry.actor_did.as_bytes().to_vec())
                    .expect("canonical policy actor DID"),
                *graph.entry.actor_device_id.as_bytes(),
            )
            .expect("canonical policy actor");
            let planned = plan_policy(
                prior,
                actor,
                control.transition,
                Sha256::digest(control.transition_id.as_bytes()).into(),
            )
            .expect("genuine entry-bearing policy plans");
            let plan = persistence_plan_for_test(
                planned,
                ConversationHeadCasBinding::for_test_edge(
                    *cid.as_bytes(),
                    *control.entry.entry_id.as_bytes(),
                    *prior.coordinate(),
                    5,
                    control.received_at,
                ),
            );
            let context = ExecutionContext {
                protocol_instance_id: Uuid::nil(),
                applied_at: control.received_at_db,
                actor: ExecutionActor {
                    user_did: graph.entry.actor_did.clone(),
                    device_id: graph.entry.actor_device_id,
                    key_id: graph.entry.actor_key_id.clone(),
                    auth_generation: 1,
                    role: TransitionActorRole::Admin,
                    device_status: "active".to_owned(),
                },
                authority: ExecutionAuthority::Entryless {
                    operation_id: Uuid::new_v4(),
                },
                spine: SpineArtifacts {
                    public_snapshot_bytes: Vec::new(),
                    public_snapshot_sha256: Vec::new(),
                    tree_summary_bytes: Vec::new(),
                    tree_summary_sha256: Vec::new(),
                    leaf_count: 2,
                    genesis_group_info_bytes: Vec::new(),
                    genesis_group_info_sha256: Vec::new(),
                },
                opened_leaves: Vec::new(),
                metadata_author: None,
                metadata_avatar: None,
                participant_period_ids: Vec::new(),
                leaf_period_ids: Vec::new(),
                entry_recipients: Vec::new(),
                events: Vec::new(),
                closing_leaf_periods: Vec::new(),
                closing_participant_periods: Vec::new(),
                reset_request_row: None,
                recovery_open: None,
                welcome_expiry: None,
                welcome_response: None,
                welcome_dispositions: Vec::new(),
            };
            (plan, context)
        }

        #[tokio::test]
        #[ignore = "requires the dedicated append-only gate database"]
        async fn g6_entry_bearing_executor_rejects_entryless_authority_before_writes() {
            let pool = g6_gate_pool("entry-bearing authority proof").await;
            let (graph, fixture) = g6_revocation_preflight_fixture(&pool).await;
            let (plan, context) = g6_policy_plan(&graph, &fixture.conversation_state);
            let cid = Uuid::from_bytes(graph.entry.cid);

            let mut tx = pool.begin().await.expect("begin policy authority probe");
            let error =
                apply_conversation_persistence_plan_unscoped_for_test(&mut tx, &plan, &context)
                    .await
                    .expect_err("entry-bearing policy must reject Entryless authority");
            assert!(matches!(
                error,
                ExecutorError::MissingContext("control-entry authority")
            ));
            let head: (i64, i64) = sqlx::query_as(
                "SELECT current_state_version,next_entry_seq FROM chat.conversations \
                 WHERE conversation_id=$1",
            )
            .bind(cid)
            .fetch_one(&mut *tx)
            .await
            .expect("read policy head");
            assert_eq!(head, (3, 5), "rejected policy changed the head");
            let seq_five: i64 = sqlx::query_scalar(
                "SELECT count(*) FROM chat.transitions \
                 WHERE conversation_id=$1 AND entry_seq=5",
            )
            .bind(cid)
            .fetch_one(&mut *tx)
            .await
            .expect("count policy residue");
            assert_eq!(seq_five, 0, "rejected policy appended a transition");
            tx.rollback()
                .await
                .expect("rollback policy authority probe");
        }

